class Grouper:
    """
    This class provides a lightweight way to group arbitrary objects
    together into disjoint sets.

    A Set (as defined in this class) is a collection of objects that are
    also in the same group.  A user can incrementally add objects to a
    group and then get all the objects in a group.

    There is no expectation that an object's hash which is guaranteed to
    be unique in python is unique in this class.
    """

    def __init__(self, init=()):
        """
        Parameters
        ----------
        init : list of objects
        """
        self._objects = {x: {x} for x in init}

    def __getstate__(self):
        return {'_objects': self._objects}

    def __setstate__(self, state):
        self._objects = state['_objects']

    def __contains__(self, item):
        return item in self._objects

    def __getitem__(self, item):
        return self._objects[item]

    def __len__(self):
        return len(self._objects)

    def __iter__(self):
        return iter(self._objects)

    def add(self, item):
        """
        Add a single item to the group.

        Parameters
        ----------
        item : hashable item
        """
        if item not in self._objects:
            self._objects[item] = {item}

    def remove(self, item):
        """Remove an item from the group."""
        if item not in self._objects:
            raise ValueError(f'{item!r} is not in the group')
        self._objects.pop(item)

    def groups(self):
        """
        Return a list of groups, each as a set of objects.
        """
        return list(self._objects.values())

    def siblings(self, item):
        """
        Return a set of all objects in the group containing *item*.
        """
        return self._objects[item]

    def join(self, a, *args):
        """
        Join *a* and all items in *args* into a single group.

        Parameters
        ----------
        a : hashable item
            The item to join with the others.
        *args : hashable items
            The items to join with *a*.
        """
        group = self._objects.setdefault(a, {a})
        for b in args:
            if b not in self._objects:
                self._objects[b] = group
            else:
                group |= self._objects[b]
                for c in self._objects[b]:
                    self._objects[c] = group
